"use strict";(self.webpackChunkwhaleal_platform=self.webpackChunkwhaleal_platform||[]).push([[128],{9441:function(e,t,a){a.d(t,{eC:function(){return o},eu:function(){return s},hB:function(){return n}});const n=[{id:"start",title:"Getting started",blurb:"From an empty account to a message that actually left the building — and a plan that fits."},{id:"channels",title:"Channels and connections",blurb:"You keep your own provider account. This is what that means in practice, and how to route across several."},{id:"api",title:"API and delivery",blurb:"Programmatic sending, keys, statuses, receipts, rate limits and the message log."},{id:"scale",title:"Sending at scale",blurb:"Lists, batches and scheduled sends — with pacing that protects your provider limits."},{id:"compliance",title:"Opt-out and data",blurb:"What happens after a recipient replies STOP, and what the platform stores about your messages."},{id:"troubleshooting",title:"Troubleshooting",blurb:"Diagnosing the cases where everything returns success and the message still does not arrive."}],o=[{slug:"getting-started",category:"start",title:"Getting started",excerpt:"Connect a provider, issue a key, send your first message — and meet the two defaults that quietly cost money if you miss them.",readMinutes:5,updated:"2026-10-13",sections:[{h:"What you get",p:["Whaleal Messaging is a sending layer in front of the provider accounts you already own. You keep your CPaaS contracts, your sender numbers and your delivery reputation; the platform adds a console and a message log for the connections you make, with the send API documented per channel."],list:["HTTPS endpoints to send over the connected accounts, documented per channel.","Weighted routing and automatic failover across providers and sender numbers.","Delivery receipts and terminal status pushed back to a callback URL you control.","Opt-out suppression that blocks marketing sends to a number that replied STOP.","A metadata-only message log, retained per your plan."],scope:"Everything described in these articles is the SMS channel. Email and WhatsApp connect on the same model — link your own provider account and send from the console."},{h:"Set up in three steps",p:["All three live in the console, and all three are required. Miss one and a send is rejected rather than silently dropped — which is the behavior you want."],steps:[{h:"Connect a provider",p:"Channels → Add connection, pick a channel, then paste the credentials of a CPaaS account you already hold. On SMS the connectable set is Twilio, Vonage, Infobip, MessageBird, Plivo and AWS End User Messaging; email and WhatsApp work on the same model with their own providers. The console shows the current list for every channel — that list is the authority, not this page."},{h:"Issue an API key",p:"Developer → Create key. The full key is shown once, shaped sk_…. Copy it immediately; it cannot be displayed in full again."},{h:"Bind the key to a channel",p:'On the same page, select the channels this key may send over. A key with no binding is rejected with a 400-class error — there is no "all channels" fallback.'}]},{h:"Send your first message",p:["With a key in hand, a single call is enough:"],table:{head:["Item","Value"],rows:[["Method and path","POST /open/v1/sms/send"],["Base URL","https://api.whaleal.com/open/v1"],["Auth header","Authorization: Bearer sk_… (or X-API-Key)"],["Body",'{"to":"+14155550123","content":"Your code is 4481","messageType":"TRANSACTIONAL"}']]},note:"A success response means the platform accepted the message, not that a handset received it. To learn the real outcome, either poll GET /open/v1/sms/{messageId} or configure a callback URL."},{h:"Two defaults that cost money",p:["Both are easy to make once and hard to notice, because neither produces an error."],list:["Omitting messageType on verification codes and order confirmations. The default is MARKETING, so a recipient who has opted out will have their verification code suppressed. Declare TRANSACTIONAL or INFORMATIONAL on anything that is not a promotion.",'Retrying after a client-side timeout. The platform does not de-duplicate: a retry is a second message, sent and billed. See "Messages are accepted but not arriving".']}]},{slug:"plans-and-billing",category:"start",title:"Plans, quotas and billing",excerpt:'What each tier includes, how a "channel" is counted, and why your SMS fees never appear on our invoice.',readMinutes:4,updated:"2026-10-13",sections:[{h:"What the subscription pays for",p:["The subscription covers channel management on the platform. The messages themselves are billed by your own provider, at the rate you negotiated with them — the platform never touches, marks up or resells SMS traffic.","That split is the practical meaning of bring-your-own-account: one invoice from your provider for traffic, one small subscription here for the management layer."]},{h:"The four plans",p:["Sending volume is not capped on any tier. Plans differ only in how many channels you may connect, the submission rate, and how long the message log is kept."],table:{head:["Plan","Price","Channels","Submit rate","Log retention"],rows:[["FREE","$0","1","10 QPS","7 days"],["GROWTH","$19/mo · $180/yr","3","50 QPS","7 days"],["PRO","$49/mo · $480/yr","10","100 QPS","30 days"],["ULTRA","$199/mo · $2,000/yr","Unlimited","500 QPS","90 days"]]},scope:"Figures above mirror the current pricing page. Check the pricing page for what applies to your account, and treat this table as a summary rather than the contract."},{h:"How channels are counted",p:["A channel is a provider account, not a phone number. Ten sender numbers under one Twilio account still count as one channel — and all ten join the platform's weighted rotation."]},{h:"Change plan",steps:[{h:"Open Billing in the console",p:"The current plan and its renewal date are shown at the top."},{h:"Pick a paid tier",p:"Growth, Pro or Ultra opens a Stripe checkout. Free needs no checkout — it is the permission set you get by default."},{h:"Confirm the change",p:"Upgrades take effect immediately; the new limits apply as soon as the payment clears."}],note:"If a renewal payment fails, the account enters a grace period before it is downgraded to Free. A cancellation takes effect at the end of the paid period rather than immediately."}]},{slug:"connect-a-provider",category:"channels",title:"Connect your own provider account",excerpt:"Bring-your-own-account keeps the agreement, the sender reputation and the invoice with your CPaaS provider. Here is how to connect one, and what changes once you do.",readMinutes:5,updated:"2026-10-13",sections:[{h:'What "your own account" means',p:["You connect an account you already hold. The platform stores the credentials you paste, routes through your account, and never becomes the party your provider invoices.","This is the difference that matters commercially: the pricing you negotiated, the sender numbers you already registered, and the delivery reputation you have built all stay where they are."],scope:"The connectable set is whatever the console lists when you add a connection — on SMS, email and WhatsApp alike. A provider outside that list cannot be connected yet: register it as a request from the console so it is counted rather than lost."},{h:"Which credentials the SMS providers expect",p:["Every provider asks for a different pair. The console labels every field and refuses to save until all required fields are present. The email and WhatsApp providers each have their own field list on their page under Integrations."],table:{head:["Provider","Credentials"],rows:[["Twilio","Account SID + Auth Token (account-level, not an API key pair)"],["Vonage","API key + API secret"],["Infobip","API key + base URL"],["MessageBird","Access key"],["Plivo","Auth ID + Auth token"],["AWS End User Messaging","Access key + secret + region"]]}},{h:"Connect a provider",steps:[{h:"Add a connection",p:"Channels → Add connection, then choose the provider type."},{h:"Paste the credentials",p:"Use the field labels above as a checklist. Nothing is sent anywhere until you save."},{h:"Save and confirm the status",p:"The connection appears in the list. Its status becomes ACTIVE once the platform has accepted the credentials."}],note:"Credentials are encrypted before they are stored and are never shown in full again. Copy them from your provider dashboard if you need to check them later."},{h:"What ACTIVE does and does not mean",p:["ACTIVE means the credentials validated. It does not promise that a given sender number is accepted by the provider, or that a destination country is reachable on that route.",'Those refusals surface per message, as a failed status with an error code — see "Messages that fail with an error code".']},{h:"Editing and removing a connection",p:["A masked credential field is not a value you have to retype. Editing any field on the form re-encrypts only what you actually changed, so the stored secret survives an unrelated edit.","Removing a connection takes its sender numbers out of the rotation. An API key bound to it will have one fewer channel to send over — and a key left with no bound channel is rejected at send time."]}]},{slug:"sender-numbers",category:"channels",title:"Sender numbers and how they are chosen",excerpt:"Most senders never specify a from address, and that is usually correct. Here is when to override it.",readMinutes:3,updated:"2026-10-13",sections:[{h:"Default behavior",p:["Leave from out of the request and the platform injects a sender from the connection's configured list. When a connection holds several senders, they are rotated with smooth weighted round-robin, and the caller is not told which one carried the message.","For most integrations this is the behavior you want: you do not have to track which number is currently healthy."]},{h:"When to specify from explicitly",p:["An explicit from always wins over the automatic choice. Reach for it when the number is part of the message's meaning rather than its infrastructure."],list:["A support line the recipient is expected to reply to.","A number already published on a website or an invoice.","A per-region or per-brand number where the sender itself carries information."]},{h:"Reply matching does not depend on the sender",p:["Opt-out suppression is keyed on tenant plus recipient number, not on the sending number. Rotating senders will not route around a STOP, and changing the sender does not reset anyone's consent state."]}]},{slug:"route-between-channels",category:"channels",title:"Route across providers with priority and weight",excerpt:"Bind a key to more than one provider and the platform becomes the routing layer — balancing load when all is well, failing over when it is not.",readMinutes:5,updated:"2026-10-13",sections:[{h:"Two dials, two jobs",p:["Routing is controlled by two independent numbers on each channel. They answer different questions, which is why using only one of them cannot express both common setups."],table:{head:["Dial","What it decides","When it acts"],rows:[["priority","Which channel takes over when another fails","Only when a channel fails"],["weight","How traffic is split while all channels are healthy","Only while all are healthy"]]},p2:['The distinction is deliberate: weight alone cannot express "keep the backup idle until the primary breaks", and priority alone cannot express "send three for every one".']},{h:"The rule at send time",list:["All weights equal → ordered failover. The lowest priority number is tried first and the rest stand by until it fails.","Weights not all equal → smooth weighted round-robin, so the split follows the weight ratio, with the remaining channels covering failures."],note:"The send response and every receipt name the provider that actually carried the message, so reconciliation never depends on guessing which channel was used."},{h:"Turn it on",steps:[{h:"Connect a second provider",p:"Channels → Add connection, one per provider account you want in the rotation."},{h:"Bind the key to both",p:"A single API key can send over several channels. This is what puts the platform in the routing path."},{h:"Set priority and weight",p:"Give each channel its failover order and its share of healthy traffic."},{h:"Verify with one send",p:"Read the provider field in the response — it tells you which channel carried the message."}]},{h:"Sender numbers rotate inside a channel too",p:["A channel's sender numbers are expanded into virtual channels that join the same rotation, weighted by channel weight × sender weight. Rotating senders is how you work around a provider's per-number concurrency limit without changing your integration.","The rotation is transparent: you keep sending to the same endpoint, and the platform decides which number leaves the building."]}]},{slug:"api-keys",category:"api",title:"Create, bind and rotate API keys",excerpt:"A key proves which tenant is calling and which channels it may use. It is shown in full once, and a key with no binding cannot send at all.",readMinutes:3,updated:"2026-10-13",sections:[{h:"What a key carries",p:["A key is not just an identifier — it pairs a tenant with a set of permitted channels. The server checks both on every request, so a key is also the narrowest available way to scope what an integration can do."]},{h:"Presenting the key",p:["Either header works; there is no difference in behavior between them."],table:{head:["Header","Value"],rows:[["Authorization","Bearer sk_…"],["X-API-Key","sk_…"]]}},{h:"Create a key",steps:[{h:"Open Developer in the console",p:"This page lists existing keys and their bindings."},{h:"Create the key",p:"The full value is displayed once, shaped sk_…. Store it the way you store any other production credential."},{h:"Bind it to channels",p:"Select one or more channels the key may send over. Multiple bindings are allowed and are load-balanced."}]},{h:"Handling and rotation",p:["Keys can be revoked and rotated from the console at any time. Because a key is bound to specific channels, rotating one is also how you narrow what a compromised integration is able to do."],list:["A missing or invalid key returns HTTP 401 with code 40100.","A valid key bound to no channel is rejected with code 40000, not 401 — the key was fine, the permission was not.","Being bound to a channel that is not ACTIVE is also a 40000-class rejection."]}]},{slug:"send-a-message",category:"api",title:"Send a message with the API",excerpt:"One endpoint accepts asynchronously. A success code means the platform took the message — not that a handset received it.",readMinutes:6,updated:"2026-10-13",sections:[{h:"The call",p:["Endpoint and headers below. All request and response bodies are UTF-8 JSON."],table:{head:["Item","Value"],rows:[["Method and path","POST /open/v1/sms/send"],["Base URL","https://api.whaleal.com/open/v1"],["Auth","Authorization: Bearer sk_… (or X-API-Key)"],["Content-Type","application/json"]]}},{h:"Fields worth reading twice",table:{head:["Field","Required","Why it matters"],rows:[["to","Yes","E.164 format. Opt-out matching compares digits after stripping + and separators, so inconsistent formatting is what makes a STOP fail to match"],["content","Yes","Not stored on the platform, for compliance. Keep your own copy if you need one"],["from","No","Omit it and the platform picks a sender from the connection"],["messageType","No","MARKETING / INFORMATIONAL / TRANSACTIONAL. Omitted means MARKETING, the strictest setting"],["templateId","No","Only for providers that bill or approve per template — pass a template ID you created in your own provider account"]]},note:"The platform sends the content you give it. It does not render template variables for you, and template definitions live in your provider account, not here."},{h:"Start with TRANSACTIONAL, not with the default",p:["messageType is the only input to the suppression gate. The platform does not read your message body — so an alert that happens to contain promotional wording will pass as TRANSACTIONAL even though, under rules like the US TCPA, it may still be legally marketing. Declaring the type honestly is the caller's responsibility.","An unrecognised value is rejected with HTTP 400 and code 40000 rather than silently downgraded. That is deliberate: a typo should surface as a broken integration, not as verification codes that quietly stop arriving."],scope:"Suppression applies to marketing traffic only, and opt-out handling is an SMS concept here. Email and WhatsApp connect on the same model, but they do not carry this suppression gate today."},{h:"What comes back",p:["The response repeats the recipient, names the provider that actually carried the message, and returns the fields you will want at reconciliation time."],table:{head:["Field","Meaning"],rows:[["messageId","Platform message ID. Use it for status lookups and for de-duplicating callbacks"],["status",'Where the message stands right now — see "What each message status means"'],["providerMessageId","Provider-side ID. Null means the provider did not accept it, which also means it is not billed"],["rawStatus","The provider's own wording before normalization — diagnostic value only"],["encoding","GSM7 / UCS2 / UTF8 / GBK — the encoding actually used"],["segments","Billed segments for this message"]]}},{h:"The one rule that prevents most duplicate sends",p:["There is no idempotency key. Sending the same request twice sends two messages and bills for two. Because acceptance is asynchronous, a network timeout means the send may already have happened — treat the timeout as unknown, not as failure."],list:["Got a messageId: query its status or wait for the callback. Do not resend.","Did not get a messageId: look the send up in the console log by time window and recipient number. Do not resend.","A client-side timeout never rolls back a message that was already submitted."]}]},{slug:"message-statuses",category:"api",title:"What each message status means",excerpt:"Four states, and one of them does not belong in the same bucket as the others. Reading suppressed as a failure sends you looking in the wrong place.",readMinutes:4,updated:"2026-10-13",sections:[{h:"The four states",table:{head:["Status","Meaning"],rows:[["submitted","Accepted and handed to the provider. This is where a successful send call lands — not the end of the story"],["delivered","The provider confirmed delivery to the handset"],["failed","Attempted and refused — either at submission, or later by provider receipt. errorCode carries the reason"],["suppressed","Never attempted. The platform stopped it before sending because the recipient had opted out"]]}},{h:"suppressed is not a failure",p:["A suppressed message never reached a provider, so there is no provider history to investigate. It is also not billed: providerMessageId and encoding are null, segments is 0, and it does not count toward your monthly totals.","Retrying it will not help — the recipient's opt-out state does not change because you retried. Re-enabling marketing to that number requires the recipient to express consent again."]},{h:"A success code is not a delivery",p:["The send endpoint accepts asynchronously. A success response means the platform submitted the message — it may already be on its way, or the provider may refuse it a moment later. The state that tells you the truth is delivered, which arrives by callback or by polling."],scope:"Status callbacks cover delivered and failed. A suppressed message has no callback, because its final state was decided at acceptance."}]},{slug:"delivery-receipts",category:"api",title:"Receive delivery receipts",excerpt:"The platform POSTs to a URL you configure, with a token you generate. Two implementation details decide whether you lose events.",readMinutes:5,updated:"2026-10-13",sections:[{h:"How it is set up",p:["Configure the callback URL and generate the callback token in the console, then expose an endpoint that accepts a JSON POST. The platform posts when a message reaches a terminal state.","Each request carries an X-Callback-Token header. Verify it server-side before trusting the body."],steps:[{h:"Set the callback URL",p:"Console → Settings → Webhook. Use an HTTPS endpoint that is reachable from the public internet."},{h:"Generate the webhook token",p:"The token is what proves a request came from the platform. Store it server-side, not in client code."},{h:"Expose the endpoint",p:"Accept a JSON POST, verify the header, then acknowledge with a 2xx response."}]},{h:"What arrives",table:{head:["Field","Meaning"],rows:[["messageId","Platform message ID — your de-duplication key"],["status","delivered or failed, and nothing else"],["providerMessageId","Provider-side ID"],["rawStatus","The provider's own wording, e.g. Twilio delivered or Vonage expired"],["to / provider","Recipient and the provider that carried it"],["errorCode","Reason, on failure or refusal"],["encoding / segments","Encoding used and billed segments"],["timestamp","When the platform pushed it, ISO-8601 UTC"]]}},{h:"Retries: return 2xx, and de-duplicate anyway",p:["A non-2xx response, or a timeout, is retried on a 1s / 5s / 15s backoff, three times. After that the platform gives up and records the delivery as failed.","That retry behavior means you can legitimately receive the same event twice. De-duplicate on messageId rather than assuming exactly-once delivery."],list:["Return 2xx only after you have durably accepted the event, not before.","De-duplicate on messageId.","Do not do slow work inline — a callback endpoint that takes seconds is a callback endpoint that gets retried."]},{h:"Which messages you will not hear about",p:["Suppressed messages produce no callback. They were never handed to a provider, so delivered and failed do not apply — the outcome was fixed at acceptance."]}]},{slug:"rate-limits-and-usage",category:"api",title:"Rate limits and monthly usage",excerpt:"There are two counters, they are not the same number, and only one of them looks like a bill.",readMinutes:4,updated:"2026-10-13",sections:[{h:"Submission rate is per tenant",p:["Every path that submits — API, console, bulk, scheduled — draws on one tenant-level budget. Over the limit returns HTTP 429 with code 42900, and the client is expected to back off."],table:{head:["Plan","Reqs/sec","Channels","Log retention"],rows:[["FREE","10","1","7 days"],["GROWTH","50","3","7 days"],["PRO","100","10","30 days"],["ULTRA","500","unlimited","90 days"]]},scope:"Figures above are the current published plan limits. Check the pricing page for what applies to your account."},{h:"There is a second limiter in front",p:["An edge limiter also runs, keyed on client IP and set far above any plan tier. It exists to absorb abnormal traffic rather than to shape normal use.",'It returns the same HTTP 429 and the same code 42900, so distinguish it by the message text: the edge limiter\'s message begins with "edge rate limit exceeded".']},{h:"Two counters, and the one that matters",p:["The usage endpoint reports both, and they will never be equal."],table:{head:["Field","What it counts"],rows:[["messageCount","How many times you submitted"],["billedSegments","How many billable messages you produced — long messages count as more than one, and only provider-accepted ones count"],["period","Billing period key, UTC yyyyMM"],["plan / qps","Current plan and its submission ceiling; zero or less means unlimited"]]}},{h:"Why long messages cost more than they look",p:["A single logical message can bill as several segments once it crosses the encoding limit, and that limit depends on the alphabet used. Non-GSM characters move the whole message to a wider encoding with a smaller per-segment budget.","The platform does not store message bodies, so segments cannot be recomputed after the fact. The segment count returned with each message is the only record — reconcile from it, not from the text."]}]},{slug:"message-logs-and-filtering",category:"api",title:"Find a message in the log",excerpt:'The log answers "what happened to this one message" — without storing anyone\'s content.',readMinutes:4,updated:"2026-10-13",sections:[{h:"What the log stores",p:["The log is built for operations and reconciliation, which is why it keeps metadata rather than traffic."],list:["Time, destination number, tenant, provider, sender, normalized status, provider message ID and raw error code.","The batch or campaign a message belonged to, when there was one."],scope:"Message bodies are never persisted — for compliance, and because the platform does not need them to deliver. Retention is plan-based: 7 days on Free and Growth, 30 on Pro, 90 on Ultra. Past that window records are deleted by a TTL index, so export anything you must keep."},{h:"Filter the log",steps:[{h:"Narrow by time first",p:"Start with the window around the send, then add the recipient number."},{h:"Add the recipient number",p:"This is the fastest way to isolate a single conversation, including its duplicates."},{h:"Add provider or status",p:"Use the status filter to separate suppressed from failed, and the provider filter to see whether one channel is behaving differently."},{h:"Open one message",p:"The detail view shows the full status history, raw provider wording and the error code, if any."}]},{h:"Channel comparison",p:["A comparison card aggregates your own channels side by side — submit success rate, delivery rate and latency. It is the quickest way to see that one provider account is underperforming before it shows up in customer complaints."]},{h:"Export",p:["Exports run asynchronously and are truncated at 1,000,000 rows. A truncated export is reported as truncated rather than silently shortened, so check that flag before treating a file as complete."]}]},{slug:"bulk-and-scheduled-sending",category:"scale",title:"Bulk and scheduled sends",excerpt:"Send to a list once, or at a future time, with per-batch pacing that protects your provider limits.",readMinutes:5,updated:"2026-10-13",sections:[{h:"How a batch is shaped",p:["Two decisions shape a bulk send: which contacts are in it, and which channel carries it."],list:["Adding contacts creates a batch, identified by a batch number. The batch is the unit you review and resend.","A batch sends over one channel that you pick — the whole batch goes through that single provider, with its sender numbers still rotating by weight inside it.","Pacing is applied per batch, so a large send does not exhaust the provider limits that your live traffic also depends on."]},{h:"Run a bulk send",steps:[{h:"Prepare the recipients",p:"Use a list, or import contacts by CSV. Numbers must be E.164."},{h:"Compose the message",p:"Pick the batch and the channel it should send through, then write the content."},{h:"Choose immediate or scheduled",p:"Immediate sends start as soon as you launch; a scheduled send waits for the time you set."},{h:"Watch the batch",p:"The batch view reports sent, failed, skipped and suppressed counts as it progresses."}],note:"Scheduled sends are SMS-only today. If you schedule over another channel, the platform tells you rather than silently sending immediately."},{h:"When a batch fails part-way",p:["Resending a failed batch retries only the recipients that were never attempted. Contacts that were already sent, or that are suppressed, are not sent to again — so a reset does not turn into a duplicate blast."]},{h:"Suppression counts as skipped, not failed",p:['Recipients on the suppression list are counted separately from failures. A batch can therefore report a large skipped number and still be a healthy run — see "Opt-out and suppression" for why that is the correct outcome.']}]},{slug:"contacts-and-lists",category:"scale",title:"Contacts and lists",excerpt:"Keep the people you message in one place, import them in bulk, and group them without duplicating anyone.",readMinutes:3,updated:"2026-10-13",sections:[{h:"What a contact holds",p:["A contact is a name, an E.164 phone number, and optional tags. Lists are a view over tags rather than a second copy — a person can belong to several lists without being stored several times."]},{h:"Import contacts",steps:[{h:"Open Contacts",p:"This page lists existing contacts and the batches you have imported."},{h:"Upload a CSV",p:"Map your columns to name and phone number. Numbers must be E.164."},{h:"Review the import",p:"The import lands as a batch you can inspect before you build a send from it."}],note:"A malformed number is the most common import problem. If a contact never receives anything, check its number format in the log rather than its tags."},{h:"Lists are a filter, not a folder",p:["Because lists are built from tags, updating a tag updates every list that uses it. There is no second copy to keep in sync — which is also why renaming a list never moves a contact."]}]},{slug:"opt-out-and-suppression",category:"compliance",title:"Opt-out and suppression",excerpt:"STOP, HELP and START are three different branches. Configuring only the receipt endpoint is the mistake that makes the whole chain fail silently.",readMinutes:6,updated:"2026-10-13",sections:[{h:"Three keywords, three behaviors",p:["Keywords are matched on the whole message, case-insensitively, tolerating surrounding punctuation and whitespace. Partial matches do not count."],table:{head:["Received","What the platform does"],rows:[["STOP / STOP ALL / UNSUBSCRIBE / CANCEL / END / QUIT / OPTOUT / OPT OUT (also 退订, ABMELDEN)","Adds the number to that tenant's suppression list and sends nothing further of a marketing nature"],["HELP / INFO","Replies with a fixed explanation. Does not add the number to any list"],["START / YES / UNSTOP","Removes the number from the suppression list and replies with a confirmation"]]}},{h:"Turn suppression on",steps:[{h:"Point the receipt endpoint",p:"Configure /webhook/sms/{provider}?token=… in your provider dashboard so delivery results reach the platform."},{h:"Point the inbound endpoint too",p:"Configure /webhook/sms/{provider}/inbound?token=… as well. This is the second, separate setting — and the one that is easy to forget."},{h:"Send a test STOP",p:"Reply STOP from a phone, then send a marketing message to that number and confirm it comes back suppressed."},{h:"Check the suppression list",p:"The console lists suppressed numbers and allows a manual release, alongside the automatic START keyword."}],scope:"Configure only the receipt endpoint and opt-out suppression never triggers. Nothing errors — the chain simply stays silent, which is why this is worth checking first when a STOP appears to do nothing."},{h:"What the platform will not do for you",p:["The gate reads messageType and nothing else. It does not inspect your content.","The inbound token proves which tenant the message belongs to. It does not prove the message genuinely came from that provider — provider signature verification is not implemented. Treat the token as routing, not as authentication.","Not every provider emits an opt-out keyword upstream. Where a provider handles opt-out itself at the carrier level, no inbound event is produced, so our record is a reconciliation aid rather than the only line of defense."]},{h:"Re-subscribing, and why the database being right is not enough",p:["Suppression records are not deleted on re-subscribe — the record is closed and the consent history is kept for audit. There is an operator-side console action as well as the START keyword.","Clearing the number on our side only affects our sending. In some cases, including toll-free traffic, the carrier may have blocked the number independently, and the recipient has to take their own action as well. That step cannot be performed by code."]}]},{slug:"message-content-and-retention",category:"compliance",title:"What we store, and for how long",excerpt:"The platform keeps metadata about your messages, not their content. Here is exactly what that means for your own records.",readMinutes:3,updated:"2026-10-13",sections:[{h:"Message bodies are not stored",p:["The platform does not persist the text of your messages. It is not needed to deliver them, and keeping it would mean holding customer content that carries no operational value here.","The practical consequence: if you need a record of what you sent, keep your own copy. It cannot be reconstructed from the log."]},{h:"What is stored",table:{head:["Stored","Why"],rows:[["Routing and status metadata","So the log can answer what happened to a message"],["Provider message ID and raw status","For reconciliation with your provider account"],["Suppression records and consent history","For audit, and so a STOP is not lost"],["Credentials, encrypted","So the platform can send through your provider account"]]}},{h:"Retention windows",p:["Log retention follows the plan, and records past the window are removed automatically rather than by request."],table:{head:["Plan","Log retention"],rows:[["FREE","7 days"],["GROWTH","7 days"],["PRO","30 days"],["ULTRA","90 days"]]},scope:"Suppression records are not subject to the log retention window — a consent record must outlive a message log to be worth anything."},{h:"Getting your data out",p:["The log can be exported, and the same metadata is available over the API. Exports are asynchronous and truncate at 1,000,000 rows, and a truncated export says so rather than quietly shortening the file."]}]},{slug:"messages-not-arriving",category:"troubleshooting",title:"Messages are accepted but not arriving",excerpt:"Every call returns success. Work through this in order — the first four checks do not involve the carrier at all.",readMinutes:5,updated:"2026-10-13",sections:[{h:"Check in this order",p:["Each step either finds the cause or rules out a whole layer, so a wrong guess early costs more than it saves."],steps:[{h:"Read the status",p:"suppressed means the platform never tried to send it, and no provider investigation will help."},{h:"Check messageType",p:"Transactional traffic must declare INFORMATIONAL or TRANSACTIONAL, or a recipient who opted out will have it suppressed."},{h:"Check the callback",p:"If you never configured a callback URL, you will never learn that a message failed after submission."},{h:"Check for a duplicate",p:"If you retried after a timeout, there may be two messages, and the second one may be the one the recipient sees."},{h:"Only then look at the provider",p:"Segments, encoding and errorCode on the failed message tell you whether this is an encoding, routing or carrier-side problem."}]},{h:"The timeout trap",p:["The send endpoint accepts asynchronously. Returning success means the platform submitted the message to the provider, and at that moment it may already have gone out.","So a client-side timeout is not evidence of failure. There is no idempotency key: resending produces a genuinely second message, sent and billed. If you do not have a messageId, look the send up in the console by time window and recipient number instead of resending it."]},{h:"A message that says delivered and was still not seen",p:["delivered is the provider's report that the handset received the message, which is as far as any platform can see. It does not prove a human read it. Before treating it as a platform fault, confirm the recipient has not filtered the sending number, and that the message did not land in a filtered or spam view."]}]},{slug:"message-failed-with-an-error-code",category:"troubleshooting",title:"Messages that fail with an error code",excerpt:"A failed status always carries a reason. The first question is which layer wrote it — the platform or the provider.",readMinutes:5,updated:"2026-10-13",sections:[{h:"Two kinds of code",p:["A failure is either the platform refusing the request before it left, or the provider refusing it after. The code tells you which, and therefore who owns the fix."],table:{head:["Code","Layer","Typical cause"],rows:[["40000","Platform (HTTP 400)","Bad parameter, key bound to no channel, no ACTIVE channel, messageType not recognized"],["40100","Platform (HTTP 401)","Key missing or invalid"],["40400","Platform (HTTP 404)","messageId not found, or belongs to another tenant"],["42900","Platform (HTTP 429)","Submission rate exceeded — back off and retry"],["errorCode + rawStatus","Provider","The provider's own refusal, kept verbatim so you can match it against their documentation"]]}},{h:"Work the provider refusal",steps:[{h:"Read rawStatus before errorCode",p:"It is the provider's own wording, so it matches their docs and support answers directly."},{h:"Check encoding and segments",p:"A message that unexpectedly jumped encoding can be refused for length. A wide-encoding segment budget is much smaller than a GSM one."},{h:"Check the sender number",p:"A number the provider has not approved for that route is refused per message, even on an ACTIVE connection."},{h:"Compare channels",p:"If only one provider is refusing, the log's channel comparison tells you immediately — and routing can move traffic off it while you investigate."}],note:"A provider refusal is not billed, which is a useful signal: a message with a null providerMessageId never became an accepted send on the provider side."},{h:"Platform refusals are the easy ones",p:["A 40000 on every call usually means a binding problem rather than a payload problem — most often a key that was never bound to a channel, or a connection that is no longer ACTIVE. Both are console fixes, not code changes."]}]},{slug:"duplicate-messages",category:"troubleshooting",title:"A recipient received the same message twice",excerpt:"Almost always this is a client-side timeout followed by a resend. Here is how to confirm it, and how to stop it happening.",readMinutes:3,updated:"2026-10-13",sections:[{h:"Confirm it was a resend",p:["Two sends with the same recipient and nearly identical timestamps, both accepted, is the signature of a retry. There is no idempotency key, so the platform has no way to treat the second request as the same message — it is a new message, sent and billed."],steps:[{h:"Filter the log by recipient",p:"Set the time window around the incident and add the number."},{h:"Compare the timestamps",p:"Seconds apart means a resend. Far apart means two separate requests from your side."},{h:"Check both messageIds",p:"Two distinct platform IDs with two provider IDs confirms two independent sends."}]},{h:"Prevent it",list:["Treat a client-side timeout as unknown, not as failure — the message may already be on its way.","If a request times out, look it up in the log by time window and recipient instead of resending.","De-duplicate on your side before calling the API: record that you intended to send, then reconcile against the log."],note:"Duplicate prevention has to live in the caller. The platform deliberately offers no idempotency key, so a retry is never silently swallowed."}]},{slug:"rotate-an-api-key",category:"api",title:"Rotate an API key without stopping sends",excerpt:"Replace a key in four steps so there is never a moment when nothing can send — and know what to do first if the key leaked.",readMinutes:4,updated:"2026-10-13",sections:[{h:"Why rotation is routine, not an emergency",p:["A key is a credential, and credentials accumulate exposure: a CI variable, a colleague’s laptop, a log line, a screenshot in a ticket. Rotating on a schedule turns a potential incident into a configuration change, because the team has already done it once."]},{h:"Rotate with no gap in sending",p:["The order matters: create first, revoke last. Revoking before the replacement is deployed is what turns a rotation into an outage."],steps:[{h:"Create the replacement",p:'Create a second key and bind it to the same channels the old one could send over. A key with no channel binding is rejected — there is no "all channels" fallback.'},{h:"Deploy it",p:"Put the new value into whatever holds the credential — environment variable, secret store, CI setting — and roll the service that sends."},{h:"Verify",p:"Send one message you can observe, then look it up in the log by time window and recipient. Confirm it went out under the new key."},{h:"Revoke the old key",p:"Only after a verified send. Revocation applies to new requests; messages already accepted are already on their way."}],note:"The full value of a key is shown once, at creation. If you did not copy it, create another rather than searching for a way to display it again — nothing can show it to you."},{h:"If the key already leaked",p:["Order reverses: revoke first, then create and deploy. You accept a short window where sending fails, which is better than a window where someone else sends on your account."],list:["Revoke the exposed key immediately.","Review the message log for the exposure window — metadata is enough to spot sends you did not intend: unexpected destinations, an odd time pattern, unfamiliar providers.","Issue a replacement and deploy it.","Check nothing else was left in the same place the key leaked from."]}]},{slug:"verify-a-connection",category:"channels",title:"Verify a connection before you rely on it",excerpt:"The built-in check only validates the fields you typed. Here is the test that actually proves a connection works.",readMinutes:4,updated:"2026-10-13",sections:[{h:"What the built-in check does",p:["Adding a connection runs a field-level check: required fields present, values shaped as expected. It is a form validation, not a live call to your provider — so a connection that passes the check can still fail on the first real send."],note:'Treat a passing check as "the form was filled in correctly". It is not evidence that the credentials are valid or that the sender is authorized.'},{h:"The only test that proves it",p:["Send one real message to a number you control, then read the outcome. That single send exercises credentials, sender authorization and the route to a destination — none of which the field check touches."],steps:[{h:"Send to your own number",p:"Send a message you can read. Mark it TRANSACTIONAL so suppression rules cannot quietly swallow it."},{h:"Look it up in the log",p:"Find the row for that send. It carries the message ID, the provider and the normalized status."},{h:"Read the status honestly",p:"Delivered means credentials and route are fine. Failed means read the error code. Accepted with no receipt yet means wait and re-read — absence of a receipt is not failure."}]},{h:"What a failure is telling you",list:["An authentication error means the credentials themselves are wrong, not the route.","A rejection naming the sender means the number or sender ID is not authorized for that destination — a registration problem, which is yours to resolve with the provider.","A rejection naming the destination means the country or network does not accept this sender type.",'No error at all and no arrival means the message was accepted and the outcome is still unknown — diagnose it with the "messages accepted but not arriving" article.']}],scope:"Delivery receipts come back wherever the provider reports delivery: every SMS provider, Resend on email and Meta on WhatsApp. A connection on a channel whose provider does not report delivery back can still be verified by sending, but there is no later status to read."},{slug:"estimate-message-cost",category:"scale",title:"Estimate what a send will cost",excerpt:"Segments × destinations × sender type is the whole formula. Here is how to work it out before the invoice arrives.",readMinutes:5,updated:"2026-10-13",sections:[{h:"Count segments, not characters",p:["You are not billed by characters but by segments, and a message that exceeds one segment is split — each part carries a small header, which reduces how much text fits in the parts after the first."],table:{head:["Encoding","Single segment","Per segment when split"],rows:[["GSM-7 (Latin script, basic characters)","160 characters","153 characters"],["UCS-2 (Cyrillic, Arabic, CJK, emoji)","70 characters","67 characters"]]},note:"One emoji is enough to move an otherwise Latin message into UCS-2, which more than halves the characters per segment. That single character can double the cost of a send."},{h:"Multiply by destination and sender type",p:["Cost is per segment per destination, at the rate your own provider charges you. Nothing is repriced on the way through, so the rate that applies is the one on your contract — which is exactly why estimating cost is a matter of reading your provider’s price list with the segment count in hand."],list:["A long code is usually cheaper per message but more heavily rate-limited than a short code.","Some destinations bill differently for an alphanumeric sender ID.","Concatenated segments are billed individually, not as one message."]},{h:"See what actually went out",p:["Usage is derived from the same message log the console shows, so a filtered log and a usage figure cannot disagree. After a real send, filter the log to the window and count the rows — that is the number your provider will bill."]}]},{slug:"respond-to-a-data-request",category:"compliance",title:"Respond to a data request about a recipient",excerpt:"What the platform holds about a message, what it deliberately does not, and where the data subject relationship actually sits.",readMinutes:4,updated:"2026-10-13",sections:[{h:"What the platform holds",p:["The message log stores metadata: the time, the destination number, the tenant, the provider, the sender identity, the normalized status, the provider message ID and the raw error code. Credentials are stored encrypted, and suppression records hold the judgment plus the minimum audit detail needed to explain it."]},{h:"What it deliberately does not hold",p:["Message bodies are not persisted. This is a deliberate compliance decision: a body is a real conversation, and retaining it would create retention, export and deletion obligations that metadata does not — for a benefit that amounts to one more readable column."],note:'Practically, that means a request for "the content of the messages you sent me" cannot be answered from the platform log. If you need content for your own records, your system has to keep it.'},{h:"Working through a request",steps:[{h:"Identify the number",p:"Match on the destination number in international format."},{h:"Filter the log to that number",p:"Read the metadata rows: when, which channel, which sender, what status."},{h:"Check the suppression record",p:"If the number opted out, the suppression entry is the audit trail for that decision."},{h:"Answer from your own records for content",p:"Content, consent evidence and the commercial relationship are yours, not the platform’s."}]},{h:"Where responsibility sits",p:["The relationship with the recipient is yours, so the request is answered by you. The platform processes the metadata on your instruction and does not decide who may be messaged — nothing on this page is legal advice about how your obligations apply."]}]},{slug:"provider-stopped-accepting-traffic",category:"troubleshooting",title:"A provider stopped accepting traffic",excerpt:"Telling an account-level failure apart from a bad route, and what failover can and cannot absorb for you.",readMinutes:5,updated:"2026-10-13",sections:[{h:"What it looks like",p:["Failures rise suddenly and cluster: sends that went through fine yesterday now come back rejected, while a second connected account keeps working. That contrast is the signal — the problem is attached to one connection, not to your content."]},{h:"Account-level, or route-level?",list:["Naming the credentials — the account-level problem. Something changed on the provider side: a rotated key, a suspended account, a quota exhausted.","Naming the sender — the sender identity is no longer authorized. Registration, verification or a carrier filter is the likely cause, and it is resolved with the provider.","Naming the destination — the route to a country or network is refusing this sender type. Every account may hit the same wall, so failover will not help."]},{h:"What failover does, and what it does not",p:["Automatic failover moves traffic to another connected account on the SMS channel, which absorbs an account-level failure without you intervening. It cannot absorb a route-level failure: if the rejection is attached to the destination rather than to the account, there is nothing for failover to route around."],note:"Automatic failover between connected accounts is implemented for the SMS channel and is not claimed for the email or WhatsApp channels."},{h:"Working through it",steps:[{h:"Read the error codes per connection",p:"The log records the provider’s raw error. Compare a failing account against a working one."},{h:"See whether failures cluster by destination",p:"Clustered by destination points at a route or a registration; spread across destinations points at the account."},{h:"Check whether traffic already moved",p:"If another account is carrying the volume, failover is working and your remaining task is the account that failed."},{h:"Fix the underlying cause with the provider",p:"The platform cannot lift a carrier filter, restore a suspended account or renew a registration."}]}]}];function s(){return n.map(e=>({...e,articles:o.filter(t=>t.category===e.id)})).filter(e=>e.articles.length>0)}}}]);
